const workHdr = (): TplDef['body'] => [
  { type: 'lines', align: 'right', items: ['{{org_name}}', '{{head_name}}', '', '{{applicant_name}}', '{{applicant_address}}'] },
];

const workFields = (extra: TplDef['fields'] = []): TplDef['fields'] => [
  F('org_name', 'Название компании', 'Company name', 'text', { half: true, placeholderDoc: 'Alfa Servizi S.r.l.' }),
  F('head_name', 'Руководитель (кому)', 'Head name', 'text', { half: true, placeholderDoc: 'Sig. Paolo Bianchi — Direttore Risorse Umane' }),
  F('applicant_name', 'Ваше имя', 'Your full name', 'text', { half: true, placeholderDoc: 'Marco Rossi' }),
  F('applicant_address', 'Ваш адрес', 'Your address', 'text', { half: true, placeholderDoc: 'Via Roma 15, 20121 Milano (MI)' }),
  ...extra,
];

/** Шапка официального письма: место/дата, адресат, отправитель */
const lettHdr = (to: string[], from: string[]): TplDef['body'] => [
  { type: 'lines', align: 'right', items: ['{{place}}, {{date_today}}', '', ...to, '', ...from] },
];

